import { useState, useMemo, useEffect } from "react";
import Papa from "papaparse";
import { Plus, Minus, Trash2, ClipboardCopy, Check, Package, ImageOff, Banknote, MessageCircle } from "lucide-react";

// URL pública (CSV) de la hoja "STOCK WEB" del Google Sheets real de Santos Uniformes.
// Se publica desde Archivo > Compartir > Publicar en la Web, solo esa pestaña.
const STOCK_CSV_URL = "https://docs.google.com/spreadsheets/d/e/2PACX-1vSPSnBC9z0PHGPDR7101eJvZwhMyOBkeJBUqExVzvF-OCANf_D2BRcVsbH85KdSfuD8ThhlzibMwD3v/pub?gid=118823573&single=true&output=csv";

// ---------------------------------------------------------------------------
// DATOS DE PRODUCTOS
// Fuente: listado real + precios provisto por el cliente (Libro1.xlsx).
// El precio varía por talle (no es un precio único por prenda).
// El catálogo muestra siempre el precio de LISTA (transferencia).
// El 5% de descuento por pago en efectivo se comunica como leyenda destacada,
// no se resta de los precios mostrados (así lo pidió el cliente).
//
// - "imagen": null => todavía no tenemos foto confirmada (placeholder).
//    Ya cargadas con fotos reales: Camisa Mujeres Primaria (Juvenilia),
//    Bermuda Gris, Kilt, Buzo Jardín, Buzo Primaria/Secundaria y Pollera Gimnasia
//    (fotos enviadas por el cliente).
// - "stock": no llegó todavía. Ver TODO más abajo para cuando llegue.
// ---------------------------------------------------------------------------

