const CATEGORIAS = ["Uniforme Formal", "Educación Física", "Abrigo", "Medias", "Accesorios"];

const PRODUCTOS = [
  { id: "UD-001", nombre: "Camisa Mujeres Primaria", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["6",29000],["8",30000],["10",31000],["12",32000],["14",33000],["16",34000],["S",35000],["M",36000]] },
  { id: "UD-002", nombre: "Chomba Mujeres Secundaria", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["12",25000],["14",25000],["16",26000],["S",26000],["M",27000],["L",27000]] },
  { id: "UD-003", nombre: "Chomba Varones Primaria", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["6",23000],["8",23000],["10",24000],["12",24000],["14",25000],["16",25000],["S",26000]] },
  { id: "UD-004", nombre: "Chomba Varones Secundaria", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["12",26000],["14",26000],["16",27000],["S",27000],["M",28000],["L",28000],["XL",29000],["XXL",29000]] },
  { id: "UD-005", nombre: "Pantalón Largo Gris", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["6",45000],["8",45000],["10",46000],["12",46000],["14",47000],["16",47000],["36",52000],["38",52000],["40",53000],["42",53000],["44",55000],["46",55000],["48",55000],["50",55000]] },
  { id: "UD-006", nombre: "Bermuda Gris", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["6",35000],["8",35000],["10",36000],["12",36000],["14",37000],["16",37000],["38",40000],["40",40000],["42",41000],["44",41000],["46",41000]] },
  { id: "UD-007", nombre: "Kilt", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["1 (6-8)",52000],["2 (10-12)",56000],["3 (14-16)",60000],["4 (18-20)",64000],["5 (20-22)",66000],["6",66000],["7",66000]] },
  { id: "UD-008", nombre: "Calzas", categoria: "Uniforme Formal", imagen: "data:image/jpeg;base64,",
    talles: [["6",12000],["8",12000],["10",12000],["12",12000],["14",12000],["16",12000],["20",12000],["S",12000],["M",12000]] },

  { id: "AB-001", nombre: "Buzo Jardín", categoria: "Abrigo", imagen: "data:image/jpeg;base64,",
    talles: [["2",35000],["4",35000],["6",35000],["8",35000]] },
  { id: "AB-002", nombre: "Buzo Primaria/Secundaria", categoria: "Abrigo", imagen: "data:image/jpeg;base64,",
    talles: [["6",38000],["8",38000],["10",39000],["12",39000],["14",40000],["16",40000],["S",42000],["M",42000],["L",42000]] },
  { id: "AB-003", nombre: "Polar", categoria: "Abrigo", imagen: "data:image/jpeg;base64,",
    talles: [["6",46000],["8",46000],["10",47000],["12",47000],["14",48000],["16",48000],["S",49000],["M",49000],["L",50000],["XL",50000],["XXL",51000]] },
  { id: "AB-004", nombre: "Sweater Azul V", categoria: "Abrigo", imagen: "data:image/jpeg;base64,",
    talles: [["6",34000],["8",34000],["10",35000],["12",35000],["14",36000],["16",36000],["46",38000],["48",38000],["50",39000],["52",39000],["54",40000],["56",40000]] },
  { id: "AB-005", nombre: "Jogging Azul", categoria: "Educación Física", imagen: "data:image/jpeg;base64,",
    talles: [["2",26000],["4",26000],["6",27000],["8",28000],["10",29000],["12",30000],["14",31000],["16",32000],["S",33000],["M",34000],["L",35000],["XL",36000]] },

  { id: "EF-001", nombre: "Remera Gimnasia", categoria: "Educación Física", imagen: "data:image/jpeg;base64,",
    talles: [["2",18000],["4",18000],["6",19000],["8",19000],["10",20000],["12",20000],["14",21000],["16",21000],["S",21000]] },
  { id: "EF-002", nombre: "Remera Hockey", categoria: "Educación Física", imagen: "data:image/jpeg;base64,",
    talles: [["6",25000],["8",25000],["10",26000],["12",26000],["14",27000],["16",27000],["S",28000],["M",28000],["L",28000]] },
  { id: "EF-003", nombre: "Remera Rugby", categoria: "Educación Física", imagen: "data:image/jpeg;base64,",
    talles: [["6",29000],["8",29000],["10",30000],["12",30000],["14",31000],["16",31000],["S",32000],["M",32000],["L",33000],["XL",33000],["XXL",33000]] },
  { id: "EF-004", nombre: "Short Gabardina", categoria: "Educación Física", imagen: "data:image/jpeg;base64,",
    talles: [["4",13000],["6",13000],["8",13000],["10",13000],["12",14000],["14",14000],["16",14000],["36",16000],["38",16000],["40",16000],["42",17000],["44",17000],["46",17000],["48",17000],["50",18000],["52",18000],["54",18000]] },
  { id: "EF-005", nombre: "Pollera Gimnasia", categoria: "Educación Física", imagen: "data:image/jpeg;base64,",
    talles: [["6",18000],["8",18000],["10",19000],["12",19000],["14",20000],["16",20000],["S",21000],["M",21000],["L",21000]] },

  { id: "ME-001", nombre: "Medias Blancas (Jardín)", categoria: "Medias", imagen: "data:image/jpeg;base64,",
    talles: [["20/24",5000],["25/30",5000]] },
  { id: "ME-002", nombre: "Medias Azules", categoria: "Medias", imagen: "data:image/jpeg;base64,",
    talles: [["25/30",7000],["30/36",7000],["36/40",7000],["40/44",7000]] },
  { id: "ME-003", nombre: "Medias Deporte", categoria: "Medias", imagen: "data:image/jpeg;base64,",
    talles: [["SS",14000],["S",14000],["M",14000],["L",14000],["XL",14000]] },

  { id: "AC-001", nombre: "Escudos", categoria: "Accesorios", imagen: "data:image/jpeg;base64,",
    talles: [["R",4000],["T",4000],["C",4000]] },
].map((p) => ({ ...p, talles: p.talles.map(([talle, precio]) => ({ talle: String(talle).trim(), precio })) }));

// TODO (a futuro, cuando llegue la base de stock):
// function talleDisponible(producto, talle) {
//   if (!producto.stock) return true;
//   const registro = producto.stock.find((s) => s.talle === talle);
//   return registro ? registro.cantidad > 0 : false;
// }

const fmt = (n) => n.toLocaleString("es-AR", { style: "currency", currency: "ARS", maximumFractionDigits: 0 });

export default function App() {
  const [categoriaActiva, setCategoriaActiva] = useState(CATEGORIAS[0]);
  const [carrito, setCarrito] = useState([]); // {lineId, id, nombre, talle, precio, cantidad}
  const [vista, setVista] = useState("catalogo"); // catalogo | pedido | confirmado
  const [datosCliente, setDatosCliente] = useState({ nombre: "", telefono: "" });
  const [formaPago, setFormaPago] = useState("efectivo"); // efectivo | transferencia
  const [copiado, setCopiado] = useState(false);

  // ---- Stock en vivo (leído desde Google Sheets, hoja STOCK WEB) ----
  const [stockMap, setStockMap] = useState(null); // null = todavía no cargó
  const [stockError, setStockError] = useState(false);
  const [stockDebug, setStockDebug] = useState({ estado: "cargando", filas: 0, hora: null, mensaje: "" });

  useEffect(() => {
    cargarStock();
  }, []);

  function cargarStock() {
    setStockError(false);
    setStockDebug({ estado: "cargando", filas: 0, hora: null, mensaje: "" });
    Papa.parse(STOCK_CSV_URL, {
      download: true,
      header: true,
      skipEmptyLines: true,
      complete: (res) => {
        const mapa = {};
        res.data.forEach((fila) => {
          const id = (fila["ID"] || "").trim();
          const talle = (fila["Talle"] || "").trim();
          const disponibleRaw = fila["Disponible (en vivo desde STOCK)"];
          const disponible = parseInt(disponibleRaw, 10);
          if (id && talle) mapa[`${id}-${talle}`] = isNaN(disponible) ? null : disponible;
        });
        setStockMap(mapa);
        const filasValidas = Object.keys(mapa).length;
        setStockDebug({
          estado: filasValidas > 0 ? "ok" : "vacio",
          filas: filasValidas,
          hora: new Date().toLocaleTimeString("es-AR"),
          mensaje: filasValidas > 0 ? "" : "Se recibió una respuesta pero sin filas reconocibles (revisar encabezados de columnas).",
        });
        if (filasValidas === 0) setStockError(true);
      },
      error: (err) => {
        setStockError(true);
        setStockDebug({ estado: "error", filas: 0, hora: new Date().toLocaleTimeString("es-AR"), mensaje: String(err?.message || err) });
      },
    });
  }

  // true = hay stock (o no se pudo verificar, y en ese caso preferimos no bloquear la venta)
  function hayStock(id, talle) {
    if (!stockMap) return true;
    const val = stockMap[`${id}-${talle}`];
    if (val === undefined || val === null) return true;
    return val > 0;
  }

  const productosFiltrados = useMemo(() => PRODUCTOS.filter((p) => p.categoria === categoriaActiva), [categoriaActiva]);

  function agregarAlCarrito(producto, talleObj) {
    const lineId = `${producto.id}-${talleObj.talle}`;
    setCarrito((prev) => {
      const existe = prev.find((l) => l.lineId === lineId);
      if (existe) return prev.map((l) => (l.lineId === lineId ? { ...l, cantidad: l.cantidad + 1 } : l));
      return [...prev, { lineId, id: producto.id, nombre: producto.nombre, talle: talleObj.talle, precio: talleObj.precio, cantidad: 1 }];
    });
  }

  function cambiarCantidad(lineId, delta) {
    setCarrito((prev) => prev.map((l) => (l.lineId === lineId ? { ...l, cantidad: l.cantidad + delta } : l)).filter((l) => l.cantidad > 0));
  }

  function quitarLinea(lineId) {
    setCarrito((prev) => prev.filter((l) => l.lineId !== lineId));
  }

  const totalItems = carrito.reduce((acc, l) => acc + l.cantidad, 0);
  const totalPrecio = carrito.reduce((acc, l) => acc + l.precio * l.cantidad, 0);

  const [numeroPedido, setNumeroPedido] = useState("");

  function generarNumeroPedido() {
    const d = new Date();
    const num = `SU-${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, "0")}${String(d.getDate()).padStart(2, "0")}-${String(Math.floor(Math.random() * 900) + 100)}`;
    setNumeroPedido(num);
    return num;
  }

  function textoPedido(numero) {
    const lineas = carrito.map((l) => `  • ${l.cantidad}x  ${l.nombre}  |  Talle: ${l.talle}  —  ${fmt(l.precio * l.cantidad)}`).join("\n");
    return `PEDIDO ${numero}
Cliente: ${datosCliente.nombre}
Teléfono: ${datosCliente.telefono}
Forma de pago: ${formaPago === "efectivo" ? "Efectivo (5% off)" : "Transferencia / Mercado Pago"}

${lineas}

Total: ${fmt(totalPrecio)} (${totalItems} prendas)
Precios de lista (transferencia). Pagando en efectivo: ${DESCUENTO_EFECTIVO_PCT}% de descuento.`;
  }

  function copiarPedido() {
    navigator.clipboard?.writeText(textoPedido(numeroPedido));
    setCopiado(true);
    setTimeout(() => setCopiado(false), 2000);
  }

  function enviarPedido() {
    const numero = generarNumeroPedido();
    setVista("confirmado");
    const numeroWhatsapp = "5491150100046";
    const wa = `https://wa.me/${numeroWhatsapp}?text=${encodeURIComponent(textoPedido(numero))}`;
    window.open(wa, "_blank");
  }

  return (
    <div style={{ "--navy": "#1B2A41", "--steel": "#4A5568", "--orange": "#E8823C", "--paper": "#F5F3EE", "--ink": "#21252B", "--line": "#D9D4C7" }} className="min-h-screen w-full">
      <div style={{ background: "var(--paper)", color: "var(--ink)", minHeight: "100vh", fontFamily: "'Arial Narrow', Oswald, system-ui, sans-serif" }}>
        <div className="sticky top-0 z-20">
          <header style={{ background: "var(--navy)", color: "var(--paper)" }} className="px-5 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div>
                <div style={{ fontFamily: "system-ui, sans-serif", letterSpacing: "0.04em" }} className="font-bold text-lg leading-none">SANTOS UNIFORMES</div>
                <div style={{ color: "var(--orange)", fontSize: 11, letterSpacing: "0.12em" }} className="uppercase font-semibold">Uniformes del Colegio San Pablo Maschwitz</div>
              </div>
            </div>
            <button
              onClick={() => setVista(vista === "catalogo" ? "pedido" : "catalogo")}
              style={{ border: `1px solid ${totalItems ? "var(--orange)" : "rgba(255,255,255,0.3)"}`, background: totalItems ? "var(--orange)" : "transparent" }}
              className="px-3 py-2 flex items-center gap-2 text-sm font-semibold"
            >
              <Package size={16} />
              {vista === "catalogo" ? `Pedido (${totalItems})` : "Volver al catálogo"}
            </button>
          </header>

          {vista === "catalogo" && (
            <div style={{ background: "var(--paper)" }} className="max-w-5xl mx-auto px-5 pt-4">
              <DescuentoEfectivoBanner />

              <div className="flex gap-2 overflow-x-auto pb-1 mt-4" style={{ borderBottom: "1px solid var(--line)" }}>
                {CATEGORIAS.map((c) => (
                  <button
                    key={c}
                    onClick={() => setCategoriaActiva(c)}
                    style={{
                      borderBottom: categoriaActiva === c ? "3px solid var(--orange)" : "3px solid transparent",
                      color: categoriaActiva === c ? "var(--navy)" : "var(--steel)",
                      fontWeight: categoriaActiva === c ? 700 : 500,
                    }}
                    className="px-3 py-2 whitespace-nowrap text-sm uppercase tracking-wide"
                  >
                    {c}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {vista === "catalogo" && (
          <main className="max-w-5xl mx-auto px-5 py-6">
            <div className="grid gap-4" style={{ gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))" }}>
              {productosFiltrados.map((p) => (
                <ProductCard key={p.id} producto={p} onAgregar={agregarAlCarrito} hayStock={hayStock} />
              ))}
            </div>
          </main>
        )}

        {vista === "pedido" && (
          <main className="max-w-2xl mx-auto px-5 py-6">
            <h2 className="text-xl font-bold mb-1" style={{ color: "var(--navy)" }}>Tu pedido</h2>
            <p style={{ color: "var(--steel)" }} className="text-sm mb-4">Revisá las prendas y completá tus datos para enviar el pedido.</p>

            {carrito.length === 0 ? (
              <div style={{ border: "1px dashed var(--line)" }} className="p-8 text-center">
                <p style={{ color: "var(--steel)" }}>Todavía no agregaste prendas.</p>
                <button onClick={() => setVista("catalogo")} style={{ background: "var(--navy)", color: "var(--paper)" }} className="mt-4 px-4 py-2 text-sm font-semibold">Ir al catálogo</button>
              </div>
            ) : (
              <>
                <DescuentoEfectivoBanner />

                <div style={{ border: "1px solid var(--line)", background: "white" }} className="my-4">
                  {carrito.map((l, idx) => (
                    <div key={l.lineId} style={{ borderTop: idx === 0 ? "none" : "1px solid var(--line)" }} className="flex items-center gap-3 p-3">
                      <div className="flex-1">
                        <div className="font-semibold text-sm">{l.nombre}</div>
                        <div style={{ color: "var(--steel)" }} className="text-xs">Talle {l.talle} · {fmt(l.precio)} c/u</div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button onClick={() => cambiarCantidad(l.lineId, -1)} style={{ border: "1px solid var(--line)" }} className="w-7 h-7 flex items-center justify-center"><Minus size={13} /></button>
                        <span className="w-5 text-center text-sm font-semibold">{l.cantidad}</span>
                        <button onClick={() => cambiarCantidad(l.lineId, 1)} style={{ border: "1px solid var(--line)" }} className="w-7 h-7 flex items-center justify-center"><Plus size={13} /></button>
                      </div>
                      <div className="w-20 text-right text-sm font-semibold">{fmt(l.precio * l.cantidad)}</div>
                      <button onClick={() => quitarLinea(l.lineId)} style={{ color: "#B04A3B" }}><Trash2 size={16} /></button>
                    </div>
                  ))}
                  <div style={{ borderTop: "1px solid var(--line)", background: "var(--paper)" }} className="flex justify-between p-3 font-bold text-sm">
                    <span>Total ({totalItems} prendas)</span>
                    <span>{fmt(totalPrecio)}</span>
                  </div>
                </div>

                <div style={{ border: "1px solid var(--line)", background: "white" }} className="p-4 mb-6">
                  <div className="font-semibold text-sm mb-3" style={{ color: "var(--navy)" }}>Tus datos</div>
                  <div className="grid gap-3">
                    <input placeholder="Nombre y apellido" value={datosCliente.nombre} onChange={(e) => setDatosCliente({ ...datosCliente, nombre: e.target.value })} style={{ border: "1px solid var(--line)" }} className="px-3 py-2 text-sm" />
                    <input placeholder="Teléfono / WhatsApp" value={datosCliente.telefono} onChange={(e) => setDatosCliente({ ...datosCliente, telefono: e.target.value })} style={{ border: "1px solid var(--line)" }} className="px-3 py-2 text-sm" />
                  </div>

                  <div style={{ color: "var(--steel)" }} className="text-[11px] uppercase tracking-wide mt-4 mb-1">Forma de pago</div>
                  <div style={{ border: "1px solid var(--line)" }} className="flex text-sm">
                    {[
                      { key: "efectivo", label: "Efectivo (–5%)" },
                      { key: "transferencia", label: "Transferencia" },
                    ].map((opt) => (
                      <button
                        key={opt.key}
                        onClick={() => setFormaPago(opt.key)}
                        style={{
                          flex: 1,
                          padding: "10px 12px",
                          background: formaPago === opt.key ? "var(--navy)" : "white",
                          color: formaPago === opt.key ? "white" : "var(--ink)",
                          fontWeight: 700,
                        }}
                      >
                        {opt.label}
                      </button>
                    ))}
                  </div>

                  {formaPago === "transferencia" && (
                    <div style={{ background: "var(--paper)", border: "1px solid var(--line)" }} className="mt-3 p-3 text-sm">
                      <div className="font-semibold mb-1" style={{ color: "var(--navy)" }}>Datos para transferir (Mercado Pago)</div>
                      <div><strong>Alias:</strong> dolo.galice</div>
                      <div><strong>CVU:</strong> 0000003100002584716502</div>
                      <div><strong>Titular:</strong> Dolores Galice</div>
                    </div>
                  )}
                </div>

                <button
                  disabled={!datosCliente.nombre || !datosCliente.telefono}
                  onClick={enviarPedido}
                  style={{ background: datosCliente.nombre && datosCliente.telefono ? "var(--orange)" : "var(--line)", color: "white" }}
                  className="w-full py-3 font-bold text-sm uppercase tracking-wide"
                >
                  Enviar pedido
                </button>
              </>
            )}
          </main>
        )}

        {vista === "confirmado" && (
          <main className="max-w-xl mx-auto px-5 py-8">
            <div style={{ background: "white", border: "1px solid var(--line)", fontFamily: "'Courier New', monospace" }} className="p-6">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <div className="text-xs" style={{ color: "var(--steel)" }}>ORDEN DE PEDIDO</div>
                  <div className="text-lg font-bold" style={{ color: "var(--navy)" }}>{numeroPedido}</div>
                </div>
                <div style={{ background: "var(--orange)", color: "white" }} className="text-xs px-2 py-1 font-bold">PENDIENTE</div>
              </div>

              <div style={{ borderTop: "1px dashed var(--line)", borderBottom: "1px dashed var(--line)" }} className="py-3 mb-3 text-sm">
                <div><strong>Cliente:</strong> {datosCliente.nombre}</div>
                <div><strong>Tel:</strong> {datosCliente.telefono}</div>
                <div><strong>Pago:</strong> {formaPago === "efectivo" ? "Efectivo (5% off)" : "Transferencia / Mercado Pago"}</div>
              </div>

              <div className="text-sm mb-3">
                {carrito.map((l) => (
                  <div key={l.lineId} className="flex justify-between py-1">
                    <span>{l.cantidad}x {l.nombre} (talle {l.talle})</span>
                    <span>{fmt(l.precio * l.cantidad)}</span>
                  </div>
                ))}
              </div>

              <div style={{ borderTop: "1px solid var(--ink)" }} className="pt-2 flex justify-between font-bold text-sm">
                <span>TOTAL</span>
                <span>{fmt(totalPrecio)}</span>
              </div>
              <div style={{ color: "var(--steel)" }} className="text-xs mt-3">Precio de lista (transferencia). El pago se coordina de forma manual con Santos Uniformes.</div>
            </div>

            <div className="mt-4">
              <DescuentoEfectivoBanner />
            </div>

            <button onClick={() => window.open(`https://wa.me/5491150100046?text=${encodeURIComponent(textoPedido(numeroPedido))}`, "_blank")} style={{ background: "#25D366", color: "white" }} className="w-full py-3 mt-4 text-sm font-bold uppercase tracking-wide flex items-center justify-center gap-2">
              <MessageCircle size={16} />
              Reabrir WhatsApp
            </button>
            <p style={{ color: "var(--steel)" }} className="text-xs text-center mt-2">El pedido ya se envió a WhatsApp. Si no se abrió la ventana, tocá acá para reintentar.</p>

            <div className="flex gap-3 mt-3">
              <button onClick={copiarPedido} style={{ border: "1px solid var(--line)" }} className="flex-1 py-3 text-sm font-semibold flex items-center justify-center gap-2">
                {copiado ? <Check size={16} /> : <ClipboardCopy size={16} />}
                {copiado ? "Copiado" : "Copiar pedido"}
              </button>
              <button onClick={() => { setCarrito([]); setVista("catalogo"); }} style={{ border: "1px solid var(--line)" }} className="flex-1 py-3 text-sm font-semibold">
                Nuevo pedido
              </button>
            </div>
          </main>
        )}
      </div>
    </div>
  );
}

function DescuentoEfectivoBanner() {
  return (
    <div style={{ background: "var(--navy)", border: "1px solid var(--orange)" }} className="flex items-center gap-3 px-4 py-3">
      <div style={{ background: "var(--orange)" }} className="w-9 h-9 flex items-center justify-center flex-shrink-0">
        <Banknote size={18} color="white" />
      </div>
      <div style={{ color: "white" }}>
        <div style={{ color: "var(--orange)" }} className="text-xs font-bold uppercase tracking-wide">Beneficio</div>
        <div className="text-sm font-semibold leading-tight">
          {DESCUENTO_EFECTIVO_PCT}% de descuento pagando en efectivo.
        </div>
      </div>
    </div>
  );
}

function ProductCard({ producto, onAgregar, hayStock }) {
  const primerConStock = producto.talles.find((t) => hayStock(producto.id, t.talle)) || producto.talles[0];
  const [talleSel, setTalleSel] = useState(primerConStock);
  const [agregado, setAgregado] = useState(false);

  const talleSelDisponible = hayStock(producto.id, talleSel.talle);

  function handleAgregar() {
    if (!talleSelDisponible) return;
    onAgregar(producto, talleSel);
    setAgregado(true);
    setTimeout(() => setAgregado(false), 1200);
  }

  return (
    <div style={{ background: "white", border: "1px solid var(--line)" }} className="flex flex-col overflow-hidden">
      <div style={{ aspectRatio: "1/1", background: "#EFEAE0" }} className="flex items-center justify-center">
        {producto.imagen ? (
          <img src={producto.imagen} alt={producto.nombre} className="w-full h-full object-cover" />
        ) : (
          <div className="flex flex-col items-center gap-1" style={{ color: "var(--steel)" }}>
            <ImageOff size={22} />
            <span className="text-[10px] uppercase tracking-wide">Foto pendiente</span>
          </div>
        )}
      </div>
      <div className="p-4 flex flex-col flex-1">
        <div style={{ color: "var(--steel)" }} className="text-xs font-mono mb-1">{producto.id}</div>
        <div className="font-semibold text-sm mb-1 leading-snug" style={{ color: "var(--navy)" }}>{producto.nombre}</div>
        <div className="font-bold text-lg mb-3">{fmt(talleSel.precio)}</div>

        <div className="mb-3">
          <div style={{ color: "var(--steel)" }} className="text-[11px] uppercase tracking-wide mb-1">Talle</div>
          <div className="flex flex-wrap gap-1">
            {producto.talles.map((t) => {
              const disponible = hayStock(producto.id, t.talle);
              return (
                <button
                  key={t.talle}
                  onClick={() => setTalleSel(t)}
                  title={disponible ? undefined : "Sin stock"}
                  style={{
                    border: talleSel.talle === t.talle ? "1px solid var(--orange)" : "1px solid var(--line)",
                    background: talleSel.talle === t.talle ? "var(--orange)" : disponible ? "white" : "#F2F1EC",
                    color: talleSel.talle === t.talle ? "white" : disponible ? "var(--ink)" : "#B9B4A6",
                    textDecoration: disponible ? "none" : "line-through",
                  }}
                  className="px-2 py-1 text-xs font-semibold"
                >
                  {t.talle}
                </button>
              );
            })}
          </div>
          {!talleSelDisponible && (
            <div style={{ color: "#B04A3B" }} className="text-[11px] font-semibold mt-1">Sin stock en este talle</div>
          )}
        </div>

        <button
          onClick={handleAgregar}
          disabled={!talleSelDisponible}
          style={{
            background: !talleSelDisponible ? "#D9D4C7" : agregado ? "#3F7D5C" : "var(--navy)",
            color: "white",
            marginTop: "auto",
          }}
          className="py-2 text-xs font-bold uppercase tracking-wide flex items-center justify-center gap-2"
        >
          {!talleSelDisponible ? "Sin stock" : agregado ? <><Check size={14} /> Agregado</> : "Agregar al pedido"}
        </button>
      </div>
    </div>
  );
}
